"""Demo app: 25 seeded users, one deliberately wasteful endpoint, one fast one."""

import os

from flask import Flask, jsonify

from query_budget import QueryBudgetGuard, tracked_connect

DB_PATH = os.environ.get("APP_DB", "app.db")


def create_app() -> Flask:
    app = Flask(__name__)
    QueryBudgetGuard(app)
    init_db()
    register_routes(app)
    return app


def get_db():
    return tracked_connect(DB_PATH)


def init_db() -> None:
    conn = get_db()
    conn.executescript(
        """
        CREATE TABLE IF NOT EXISTS users (
            id INTEGER PRIMARY KEY,
            name TEXT NOT NULL
        );
        CREATE TABLE IF NOT EXISTS orders (
            id INTEGER PRIMARY KEY,
            user_id INTEGER NOT NULL REFERENCES users(id),
            total REAL NOT NULL
        );
        """
    )
    cur = conn.execute("SELECT COUNT(*) AS n FROM users")
    if cur.fetchone()["n"] == 0:
        conn.executemany(
            "INSERT INTO users (name) VALUES (?)",
            [(f"user-{i}",) for i in range(1, 26)],
        )
        conn.executemany(
            "INSERT INTO orders (user_id, total) VALUES (?, ?)",
            [
                (uid, float(uid * 10 + k))
                for uid in range(1, 26)
                for k in range(uid % 4 + 1)
            ],
        )
        conn.commit()
    conn.close()


def register_routes(app: Flask) -> None:
    @app.get("/reports/naive")
    def naive_report():
        """Deliberately wasteful: one SELECT per row over the 25 users."""
        conn = get_db()
        users = conn.execute("SELECT id, name FROM users").fetchall()
        report = []
        for user in users:
            row = conn.execute(
                "SELECT COUNT(*) AS n, COALESCE(SUM(total), 0) AS total "
                "FROM orders WHERE user_id = ?",
                (user["id"],),
            ).fetchone()
            report.append(
                {"id": user["id"], "name": user["name"],
                 "orders": row["n"], "total": row["total"]}
            )
        conn.close()
        return jsonify(report)

    @app.get("/reports/fast")
    def fast_report():
        """Efficient: a single grouped query for all users."""
        conn = get_db()
        rows = conn.execute(
            "SELECT u.id, u.name, COUNT(o.id) AS n, COALESCE(SUM(o.total), 0) AS total "
            "FROM users u LEFT JOIN orders o ON o.user_id = u.id "
            "GROUP BY u.id ORDER BY u.id"
        ).fetchall()
        report = [
            {"id": r["id"], "name": r["name"], "orders": r["n"], "total": r["total"]}
            for r in rows
        ]
        conn.close()
        return jsonify(report)


if __name__ == "__main__":
    create_app().run(debug=True)

